def semver_sort(versions):
    def parse_key(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            pre_key = None
        else:
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident), ident))
                else:
                    pre_key.append((1, 0, ident))
        return (major, minor, patch, pre is None, pre_key)

    return sorted(versions, key=parse_key)

